import {noteName,copy} from './music.js';
import {PERFORMANCE_DEFAULTS,PERFORMANCE_PRESETS,planPerformance} from './performance.js';
const $=s=>document.querySelector(s),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),bar=beat=>+(beat/4+1).toFixed(4);
export function createPerformanceUI({getProject,getRevision,getSelection,commit,protectedChange,modal,toast}){
 return function showPerformance(initialScope){
  const before=copy(getProject()),selection=copy(getSelection()),tid=selection.trackId,track=before.tracks.find(t=>t.id===tid),at=getRevision();if(!track)return toast('目标轨道已不存在');let result=null,page=0,controls={...PERFORMANCE_DEFAULTS,seed:before.seed>>>0};
  const initial=initialScope||(selection.ids.length?'selected':selection.clipId?'clip':'track'),slider=(key,label,min,max,hint,suffix='')=>`<div class="performance-field"><label for="performance-${key}"><span>${label}</span><output id="performance-output-${key}">${controls[key]}${suffix}</output></label><input id="performance-${key}" data-performance-slider="${key}" type="range" min="${min}" max="${max}" step="1" value="${controls[key]}" aria-label="${label}"><div class="performance-exact"><small>${hint}</small><input id="performance-value-${key}" data-performance-value="${key}" type="number" min="${min}" max="${max}" step="1" value="${controls[key]}" aria-label="${label}精确值"></div></div>`;
  modal('演奏整理 · 先看看，再应用',`<div class="performance-form"><p><strong>${escape(track.name)}</strong> · 整理已经写好的音符，不重新编曲，不调用模型，也不播放声音。整理包含范围内已静音音块的音符，不取消静音。</p><label class="modal-label" for="performance-scope">只整理哪里</label><select id="performance-scope"><option value="selected" ${initial==='selected'?'selected':''} ${selection.ids.length?'':'disabled'}>所选音符 · ${selection.ids.length} 个</option><option value="clip" ${initial==='clip'?'selected':''} ${selection.clipId?'':'disabled'}>当前音块</option><option value="track" ${initial==='track'?'selected':''}>整条轨道</option></select><div class="performance-presets">${PERFORMANCE_PRESETS.map(p=>`<button class="quiet" data-performance-preset="${p.id}"><strong>${p.name}</strong><small>${p.description}</small></button>`).join('')}</div><div class="performance-fields">${slider('velocityScale','演奏力度',25,200,'乘原力度；100% 不变，触顶 / 触底会提示。','%')}${slider('velocitySpread','力度的小变化',0,20,'给每个音符增加少量正负变化；0 不增加。')}</div><label class="modal-label" for="performance-timing">音符的微时间</label><select id="performance-timing"><option value="keep">保留原微偏移</option><option value="clear">清除微偏移 · 保留全局摇摆</option><option value="natural">重新生成一点松紧 · 不叠加旧偏移</option></select><div class="performance-fields">${slider('timingAmount','时间松紧',0,100,'原本同起点的所选和弦共用偏移；最大 ±0.04 拍。','%')}<div class="performance-field"><label for="performance-grid">起点对齐</label><select id="performance-grid"><option value="0">不移动原起点</option><option value="0.125">1/32 · 八分之一拍</option><option value="0.25">1/16 · 四分之一拍</option><option value="0.5">1/8 · 半拍</option><option value="1">1/4 · 一拍</option></select><label class="performance-strength" for="performance-value-strength">对齐程度（0–100%）<input id="performance-value-strength" type="number" min="0" max="100" value="100"></label><small>只对齐起点，不量化长度；放不下原长度会整组拒绝，不换音块。</small></div></div><details class="chord-advanced"><summary>更多设置 / 重叠保护与演奏种子</summary><label class="modal-label" for="performance-overlap">同音高音符重叠</label><select id="performance-overlap"><option value="keep">保留原长度 · 只提示，不自动删除</option><option value="trim">缩短范围内的前音，避免重叠</option></select><p class="review-caption">根据实际起音（含全局摇摆与微偏移）检查，与选区有关的全部同音高配对。只允许缩短范围内的前音，范围外音符永远不改；同时起音、太短或范围外前音造成的重叠会整组拒绝。包络余音 / 效果器尾音不算 MIDI 音符重叠。</p><div class="performance-seed"><label for="performance-seed">演奏种子<input id="performance-seed" type="number" min="0" max="4294967295" step="1" value="${controls.seed}"></label><button id="performance-new-seed" class="quiet compact">换一个种子</button></div></details><div id="performance-summary" class="performance-summary" aria-live="polite"></div><div id="performance-changes"></div><div id="performance-error" role="status" class="export-progress"></div><div class="modal-notice">预设 / 滑杆只改草稿；应用前先保存旧工程，一次撤销可恢复。音高、音块位置、其他音符、音色和混音保持；只有明确选“缩短前音”才改长度。发生变化的共享实例会独立化，源乐句和其他引用不改。清除微偏移不会关闭顶部全局摇摆。连续多次应用力度比例 / 力度变化会累积；固定工程与种子可重现松紧，重新打开仍默认不改动。</div></div>`,'<button class="quiet" data-close>取消</button><button class="accent" id="performance-apply">应用整理</button>');
  const guard=()=>{const current=getSelection();if(at!==getRevision()||current.trackId!==selection.trackId||current.clipId!==selection.clipId)throw Error('工程或音块选择已改变，请关闭后重新打开演奏整理。')};
  const read=()=>{guard();return planPerformance(before,tid,{scope:$('#performance-scope').value,ids:selection.ids,clipId:selection.clipId,controls:{...controls,strength:+$('#performance-value-strength').value,grid:+$('#performance-grid').value,timing:$('#performance-timing').value,overlap:$('#performance-overlap').value,seed:$('#performance-seed').value===''?NaN:+$('#performance-seed').value}})};
  const drawRows=()=>{const rows=result?.changes||[],pages=Math.max(1,Math.ceil(rows.length/12));page=Math.min(page,pages-1);const shown=rows.slice(page*12,(page+1)*12);$('#performance-changes').innerHTML=rows.length?`<details class="performance-table" open><summary>逐音查看 · ${rows.length} 个音符有变化</summary><div class="performance-table-scroll"><table><thead><tr><th>音符</th><th>名义小节</th><th>力度</th><th>实际起音变化</th><th>长度（拍）</th></tr></thead><tbody>${shown.map(x=>`<tr><th>${noteName(x.after.pitch)}</th><td>${bar(x.before.start)} → ${bar(x.after.start)}</td><td>${x.before.velocity} → ${x.after.velocity}</td><td>${((x.beatAfter-x.beatBefore)*60000/before.bpm).toFixed(2)} ms</td><td>${x.before.duration} → ${x.after.duration}</td></tr>`).join('')}</tbody></table></div><div class="performance-pagination"><button class="quiet compact" id="performance-prev" ${page===0?'disabled':''}>上一页</button><span>${page+1} / ${pages} 页</span><button class="quiet compact" id="performance-next" ${page===pages-1?'disabled':''}>下一页</button></div></details>`:'';if($('#performance-prev'))$('#performance-prev').onclick=()=>{page--;drawRows()};if($('#performance-next'))$('#performance-next').onclick=()=>{page++;drawRows()}};
  const update=()=>{$('#performance-timingAmount').disabled=$('#performance-timing').value!=='natural';$('#performance-value-timingAmount').disabled=$('#performance-timing').value!=='natural';$('#performance-value-strength').disabled=+$('#performance-grid').value===0;try{result=read();page=0;const r=result.report;$('#performance-summary').innerHTML=`<span class="eyebrow">无声预览 · 尚未应用</span><h3>${r.targetCount} 个音符中，${r.changed} 个将改变</h3><div class="performance-badges"><span>力度 ${r.velocity}</span><span>微偏移 ${r.timing}</span><span>起点 ${r.moved}</span><span>缩短 ${r.shortened}</span></div><p>同音高重叠：${r.overlapBefore.count} → ${r.overlapAfter.count} 对 ${r.overlapAfter.count?'· 未自动删除音符':'· 不含音色余音'}</p>${r.clampedVelocity?`<p>${r.clampedVelocity} 个力度触及 1 / 127 上限，已限制。</p>`:''}${r.limitedTiming?`<p>${r.limitedTiming} 个音符的松紧受音块边界限制。</p>`:''}${r.detached?`<p class="pattern-local-notice">↔ ${r.detached} 个变化的共享块将独立化；库与其他关联块保持。</p>`:''}${r.overlapAfter.count?`<details><summary>查看重叠位置（最多 30 对）</summary><ul>${r.overlapAfter.rows.map(x=>`<li>${noteName(x.pitch)} · 第 ${bar(x.start)} 小节 · ${x.earlierSelected?'前音在范围内':'前音在范围外'}</li>`).join('')}</ul>${r.overlapAfter.truncated?'<small>更多配对已计入总数，未全部展开。</small>':''}</details>`:''}`;$('#performance-error').textContent=r.blocked.join(' ');$('#performance-apply').disabled=!result.project||!r.changed;drawRows();
   }catch(error){result=null;$('#performance-error').textContent=error.message;$('#performance-apply').disabled=true;$('#performance-summary').textContent='没有应用任何改变，请检查范围与参数。';$('#performance-changes').innerHTML=''}};
  const refresh=()=>{for(const key of ['velocityScale','velocitySpread','timingAmount']){$('#performance-'+key).value=controls[key];$('#performance-value-'+key).value=controls[key];$('#performance-output-'+key).textContent=controls[key]+(key==='velocitySpread'?'':'%')}$('#performance-grid').value=controls.grid;$('#performance-value-strength').value=controls.strength;$('#performance-timing').value=controls.timing;$('#performance-overlap').value=controls.overlap;$('#performance-seed').value=controls.seed};
  document.querySelectorAll('[data-performance-slider]').forEach(input=>input.oninput=()=>{const key=input.dataset.performanceSlider;controls[key]=+input.value;$('#performance-value-'+key).value=input.value;$('#performance-output-'+key).textContent=input.value+(key==='velocitySpread'?'':'%');update()});
  document.querySelectorAll('[data-performance-value]').forEach(input=>input.oninput=()=>{const key=input.dataset.performanceValue;controls[key]=input.value===''?NaN:+input.value;$('#performance-'+key).value=input.value;$('#performance-output-'+key).textContent=(input.value||'待填写')+(key==='velocitySpread'?'':'%');update()});
  document.querySelectorAll('[data-performance-preset]').forEach(button=>button.onclick=()=>{const seed=$('#performance-seed').value;controls={...PERFORMANCE_PRESETS.find(p=>p.id===button.dataset.performancePreset).controls,seed:seed===''?NaN:+seed};refresh();update()});
  for(const id of ['scope','grid','timing','overlap'])$('#performance-'+id).onchange=update;$('#performance-value-strength').oninput=update;$('#performance-seed').oninput=update;$('#performance-new-seed').onclick=()=>{$('#performance-seed').value=Math.floor(Math.random()*0x100000000);update()};
  $('#performance-apply').onclick=async()=>{try{const latest=read();if(!latest.project||!latest.report.changed)throw Error('请先检查变化与重叠提示');$('#modal').close();await protectedChange(()=>{guard();if(commit(latest.project))toast(`已整理 ${latest.report.changed} 个音符，可整项撤销。${latest.report.detached?'变化的共享块已独立化。':''}`)},'演奏整理前 · '+before.name)}catch(error){if($('#performance-error')){$('#performance-error').textContent=error.message;$('#performance-apply').disabled=true}else toast(error.message)}};update();
 };
}
